-- MLO versions: the placements above are from zydrec-starlitemotel v1.0.2. v1.1.0 (GitHub 9389253) raised the
-- ground-floor rooms (placements milo_ .. milo__9) by 0.045 m; floors 2-3 and the room interior are unchanged.
-- The installed version is read from the MLO's fxmanifest so either version lines up exactly.
StarliteVersionOffsets = { ['1.1.0'] = { floor1 = 0.045 } }
do
    local ok, version = pcall(GetResourceMetadata, 'zydrec-starlitemotel', 'version', 0)
    local fix = ok and version and StarliteVersionOffsets[version]
    if fix then
        for _, u in ipairs(StarliteUnits) do
            if u.floor == 1 then u.origin = vector3(u.origin.x, u.origin.y, u.origin.z + fix.floor1) end
        end
    end
    StarliteMloVersion = ok and version or 'unknown'
end
